    'campo.documents.requests.due_on' => ['title' => 'Data limite', 'summary' => 'Até quando é possível entregar.', 'body' => 'A pessoa verá a data no portal. Depois do vencimento, a solicitação continua aberta e fica destacada como vencida.'],
    'campo.portal.requests.category' => ['title' => 'Tipo de solicitação', 'summary' => 'Para que chegue a quem deve atender.', 'body' => 'O tipo define quem atende sua solicitação e se você precisa anexar um arquivo.'],
    'recorrido.admin_empresa' => ['title' => 'Tour do administrador', 'summary' => 'O essencial para deixar sua organização pronta.', 'body' => "Primeiros passos: em Início você verá a lista guiada para configurar empresa, locais, estrutura e colaboradores. Cada passo leva à sua tela.\n\nConfigurações: aqui ficam usuários, perfis, fluxos de aprovação, parâmetros e a ajuda da sua organização.\n\nAjuda: o botão de ajuda da barra superior explica cada tela. Se algo não ficar claro, você pode escrever ao suporte do GestiaHR por ali."],
    'recorrido.rrhh' => ['title' => 'Tour do RH', 'summary' => 'Onde fica o seu trabalho do dia a dia.', 'body' => "Pessoas: a ficha de cada colaborador reúne dados, contratos, histórico, documentos e férias.\n\nPendências e aprovações: o que espera sua decisão aparece em Pendências; as solicitações do portal chegam em Pessoas → Solicitações.\n\nAjuda da sua organização: publique suas políticas em Configurações → Ajuda e assistente para que cada pessoa as encontre na ajuda."],
    'recorrido.payroll' => ['title' => 'Tour da folha', 'summary' => 'O que você já pode revisar enquanto a folha é ativada.', 'body' => "Colaboradores: revise regime, salário vigente, previdência e conta bancária na ficha de cada pessoa.\n\nAusências e férias: o que foi aprovado fica registrado com suas datas para o período da folha.\n\nAjuda: o botão de ajuda explica cada tela e seus campos."],
    'recorrido.recruiter' => ['title' => 'Tour de recrutamento', 'summary' => 'Para começar a preencher posições.', 'body' => "Posições: as vagas aprovadas e abertas estão em Organização → Posições.\n\nSolicitações de posição: ali se pede uma nova vaga e se acompanha a aprovação.\n\nAjuda: o botão de ajuda explica cada tela."],
    'recorrido.manager' => ['title' => 'Tour do gestor', 'summary' => 'Sua equipe em um só lugar.', 'body' => "Minha equipe: veja seus colaboradores, as datas importantes e quem está de férias.\n\nSolicitações da equipe: aprove ou rejeite férias, ausências e movimentações em Minha equipe → Solicitações.\n\nAjuda: se uma tela não ficar clara, abra a ajuda ou envie sua dúvida ao RH."],
    'recorrido.empleado' => ['title' => 'Tour do seu portal', 'summary' => 'O que você pode fazer pelo celular.', 'body' => "Seu portal: consulte seus dados, documentos e saldo de férias.\n\nSolicitações: peça férias, declarações ou envie uma solicitação ao RH e acompanhe o status.\n\nAjuda: o botão de ajuda responde dúvidas frequentes e as políticas da sua empresa. Se não bastar, envie sua dúvida ao RH."],
    'recorrido.auditor' => ['title' => 'Tour do auditor', 'summary' => 'Consulte sem alterar nada.', 'body' => "Leitura: você pode revisar fichas, documentos e movimentações conforme suas permissões; não pode alterá-los.\n\nAuditoria: cada alteração sensível fica registrada com quem, quando e o valor anterior e o novo.\n\nAjuda: o botão de ajuda explica cada tela."],
    'recorrido.sst' => ['title' => 'Tour de saúde e segurança', 'summary' => 'Para começar com sua área.', 'body' => "Colaboradores e locais: veja onde cada pessoa trabalha e seu cargo.\n\nDocumentos: os vencimentos de documentos avisam o que deve ser renovado.\n\nAjuda: o botão de ajuda explica cada tela."],
    'recorrido.investigador_denuncias' => ['title' => 'Tour do investigador', 'summary' => 'Seu acesso é restrito.', 'body' => "Você só vê os casos atribuídos a você; nada mais da organização.\n\nToda leitura de um caso fica registrada.\n\nAjuda: o botão de ajuda explica cada tela."],
    'recorrido.contador' => ['title' => 'Tour do contador', 'summary' => 'Acesso somente leitura.', 'body' => "Você pode revisar as informações contábeis que a organização compartilha, sem alterá-las.\n\nCada consulta e exportação fica registrada.\n\nAjuda: o botão de ajuda explica cada tela."],
    'novedades.1-0.base' => ['title' => 'Novidades 1.0 · Plataforma', 'summary' => 'Segurança, aprovações e ajuda.', 'body' => "- Acesso com segundo fator e com documento de identidade.\n- Fluxos de aprovação, tarefas e notificações por e-mail, SMS e WhatsApp.\n- Central de ajuda em todas as telas, com tours por perfil."],
    'novedades.1-0.core' => ['title' => 'Novidades 1.0 · Gestão de pessoas', 'summary' => 'Ficha, contratos, documentos e portal.', 'body' => "- Ficha do colaborador com histórico, remuneração e contratos.\n- Dossiê digital, modelos e declarações em PDF.\n- Portal do colaborador e do gestor, e importação do Excel."],
    'novedades.1-0.time_off' => ['title' => 'Novidades 1.0 · Férias e ausências', 'summary' => 'Saldos, solicitações e calendário.', 'body' => "- Políticas e saldos de férias por regime.\n- Solicitações com aprovação e calendário da equipe.\n- Ausências, atestados médicos e licenças legais."],
];
